// Normaliza el webhook de YCloud a { telefono, nombre, texto }.
//
// OJO con "telefono": YCloud NO siempre manda un numero. Si el cliente tiene
// nombre de usuario de WhatsApp, su numero queda oculto y en su lugar llega
// `fromUserId` (algo como "CO.2241264276652124"). Ese identificador es estable
// y sirve igual como clave de lead y de memoria, pero al responder hay que
// mandarlo en el campo `recipient` en vez de `to` (ver los nodos de envio).
//
// Se guarda tal cual, sin normalizar: si se le quitara el prefijo o se
// intentara adivinar un numero, la respuesta se iria a un hilo distinto.
const j = $json;
const raiz = j.body ?? j;
const m = raiz.whatsappInboundMessage ?? raiz.message ?? raiz;

const identidad = m.from ?? m.fromUserId ?? '';
const nombre = m.customerProfile?.name ?? m.profile?.name ?? null;

const tipo = m.type ?? 'desconocido';
const texto = tipo === 'text'
  ? (m.text?.body ?? '')
  : `[El cliente envio un mensaje de tipo "${tipo}" que no puedo leer]`;

return {
  json: {
    telefono: identidad,
    // true cuando es un numero real; los nodos de envio lo usan para decidir
    // entre `to` (E.164) y `recipient` (userId), que son excluyentes.
    es_telefono: identidad.startsWith('+'),
    nombre,
    texto,
    tipo,
    es_texto: tipo === 'text',
    wa_message_id: m.id ?? null,
    _crudo: raiz,
  },
};

// Normaliza el payload del Chat Trigger a la MISMA forma que produce
// 'Extraer Mensaje' para WhatsApp: { telefono, nombre, texto }.
// Asi el resto del flujo (upsert de lead, memoria, agente) es identico
// en los dos canales y lo que se prueba aqui es lo que corre en produccion.
//
// El sessionId del chat hace las veces de telefono: es la clave de sesion
// de la memoria y la identidad del lead. Se prefija para que un lead de
// prueba nunca colisione con un telefono real de WhatsApp.
const j = $json;
const sessionId = j.sessionId ?? 'sin-sesion';
const texto = j.chatInput ?? j.message ?? '';

return {
  json: {
    telefono: `test-${sessionId}`,
    nombre: 'Cliente de Prueba',
    texto,
    tipo: 'text',
    es_texto: true,
    wa_message_id: null
  }
};

// Normaliza el webhook MESSAGES_UPSERT de Evolution API a { telefono, nombre, texto }.
// Produce la MISMA forma que 'Normalizar Chat', para que el resto del flujo
// (upsert de lead, memoria, agente) sea identico en los dos canales.

const raiz = $json.body ?? $json;
const data = raiz.data ?? raiz;

// El JID identifica al cliente y tiene dos formas posibles:
//   573137548492@s.whatsapp.net  -> numero real, visible
//   1234567890123@lid            -> numero OCULTO por privacidad del cliente
// Con @lid no hay telefono que valga: ese JID *es* la identidad, y hay que
// devolverlo completo al responder porque Evolution no lo resuelve a un numero.
const jid = data.key?.remoteJid ?? '';
const esLid = jid.includes('@lid');
const digitos = jid.split('@')[0];

// Se guarda en E.164 (con '+') cuando es un numero real. Importante: la tabla
// `leads` viene de YCloud, que entregaba '+57...'. Si aqui se guardara sin el
// '+', cada cliente que ya existe abriria una fila nueva y perderia su
// historial y su etapa de seguimiento.
const telefono = esLid ? jid : (digitos ? '+' + digitos : '');

// Baileys reparte el texto en varias claves segun como se compuso el mensaje.
const m = data.message ?? {};
const texto =
  m.conversation                       // texto plano
  ?? m.extendedTextMessage?.text       // texto con link, respuesta o mencion
  ?? m.imageMessage?.caption           // pie de una foto
  ?? m.videoMessage?.caption           // pie de un video
  ?? null;

const tipo = data.messageType ?? (texto != null ? 'conversation' : 'desconocido');

return {
  json: {
    telefono,
    es_telefono: !esLid && digitos !== '',
    nombre: data.pushName ?? null,
    texto: texto ?? `[El cliente envio un mensaje de tipo "${tipo}" que no puedo leer]`,
    tipo,
    es_texto: texto != null,
    wa_message_id: data.key?.id ?? null,
    _crudo: raiz,
  },
};

// Normaliza el eco de un mensaje escrito a mano desde la app de WhatsApp
// Business. El envoltorio es el mismo `whatsappMessage` que usa
// `whatsapp.message.updated`, asi que quien discrimina es el `type` del evento
// (lo hace el nodo anterior), nunca la presencia de esta propiedad.
//
// En el eco los papeles estan invertidos respecto a un mensaje entrante:
//   from = el numero de la empresa   |   to = el cliente
// El que nos interesa es `to`: es la fila de `leads` que hay que pausar.
const raiz = $json.body ?? $json;
const m = raiz.whatsappMessage ?? {};

// `leads.telefono` esta en E.164 con '+'. YCloud ya lo entrega asi, pero si
// alguna vez llega en crudo de Meta (sin '+') hay que ponerselo: sin eso el
// update no encuentra la fila y el bot seguiria contestando encima del humano.
const bruto = String(m.to ?? '');
const telefono = bruto.startsWith('+')
  ? bruto
  : (/^[0-9]+$/.test(bruto) ? '+' + bruto : bruto);

return {
  json: {
    telefono,
    // 'revoke' y 'edit' tambien son ecos: el humano sigue metido en el chat.
    tipo: m.type ?? 'desconocido',
    texto: m.text?.body ?? null,
    wamid: m.wamid ?? m.id ?? null,
  },
};

// Convierte el audio descargado a base64 para mandarlo inline a Gemini.
//
// Se hace en un Code node y NO con la expresion {{ $binary.data.data }}:
// esa solo resuelve cuando n8n guarda el binario en memoria. Si la instancia
// corre en modo filesystem devuelve undefined, y el fallo seria silencioso
// (Gemini recibiria `null` y contestaria cualquier cosa).
const salida = [];
const entradas = $input.all();

for (let i = 0; i < entradas.length; i++) {
  let b64 = null;
  let mime = 'audio/ogg';
  try {
    const bin = entradas[i].binary?.data;
    if (bin) {
      const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
      b64 = buf.toString('base64');
      // Las notas de voz de WhatsApp llegan como 'audio/ogg; codecs=opus'.
      // Gemini quiere el tipo pelado: con los parametros pegados rechaza.
      mime = String(bin.mimeType || mime).split(';')[0].trim();
    }
  } catch (e) {
    b64 = null;
  }
  salida.push({ json: { b64, mime, hay_audio: b64 !== null } });
}
return salida;

// Punto de union de la rama de audio con el resto del flujo.
//
// Devuelve exactamente la misma forma que `Extraer Mensaje`, cambiando solo
// `texto` por la transcripcion. Si la transcripcion fallo por lo que sea
// (descarga caida, Gemini con error, audio ilegible), conserva el texto
// original -- que es el aviso "no puedo leer este audio". Degradar asi es
// deliberado: el cliente recibe algo util en vez de silencio.
const base = $('Extraer Mensaje').item.json;
const r = $json;

const partes = r?.candidates?.[0]?.content?.parts ?? [];
const transcrito = partes.map(p => p?.text).filter(Boolean).join(' ').trim();

// Se le pidio a Gemini que conteste SIN_VOZ cuando no hay habla. Eso no es
// una transcripcion y no debe llegar al agente como si el cliente lo hubiera
// dicho.
// OJO con el \b (2026-08-25): no se puede usar aqui. Ante un audio sin voz
// Gemini contesto "SIN_VOZ00:00", y entre la Z y el 0 NO hay frontera de
// palabra -- las dos son \w --, asi que la guarda no disparaba y al agente le
// llegaba "SIN_VOZ00:00" como si el cliente lo hubiera dicho. Verificado en
// produccion. Se ancla solo al principio y se tolera basura detras.
const invalida = !transcrito || /^\s*sin[_\s-]*voz/i.test(transcrito);

return {
  json: {
    ...base,
    texto: invalida ? base.texto : transcrito,
    es_texto: invalida ? base.es_texto : true,
    transcrito: !invalida,
  },
};

// Normaliza el aviso de que un mensaje NUESTRO no llego.
//
// Ojo con la direccion: en un evento de estado los papeles estan invertidos
// respecto a un mensaje entrante. `from` es la empresa y `to` es el cliente,
// que es la fila de `leads` que hay que marcar.
//
// El envoltorio `whatsappMessage` es el mismo que usa el eco de la app, asi
// que quien discrimina es el `type` del evento (lo hizo el nodo anterior),
// nunca la forma del payload.
const raiz = $json.body ?? $json;
const m = raiz.whatsappMessage ?? {};

// `leads.telefono` esta en E.164 con '+'. YCloud ya lo entrega asi, pero si
// alguna vez llega en crudo hay que ponerselo o el update no encuentra nada.
const bruto = String(m.to ?? '');
const telefono = bruto.startsWith('+')
  ? bruto
  : (/^[0-9]+$/.test(bruto) ? '+' + bruto : bruto);

return {
  json: {
    telefono,
    codigo: m.errorCode ?? null,
    motivo: m.errorMessage ?? 'sin detalle',
    wamid: m.wamid ?? m.id ?? null,
    // Se deja legible en la ejecucion: es lo que va a leer quien investigue.
    resumen: `No se entrego a ${telefono}: [${m.errorCode ?? '?'}] ${m.errorMessage ?? 'sin detalle'}`,
  },
};

// Divide la respuesta del agente en varios mensajes de WhatsApp reales,
// usando el separador ||| que el prompt usa entre "globos".
//
// FILTRO DE FUGA (2026-08-25). Gemini a veces devuelve la llamada a la
// herramienta como TEXTO, con `tool_calls` vacio, y el nodo del agente la toma
// por respuesta final. Sin filtro al cliente le llega literalmente
// "Calling tools: enviar_medios{categoria: sede,...}". Paso en produccion con
// un cliente real: ademas de la fuga, la herramienta no se ejecuta, asi que el
// turno se pierde. Lo unico que se puede hacer aqui es no dejar salir el texto
// y pedirle un segundo al cliente; en su siguiente mensaje el agente reintenta.
//
// El guard anterior vivia en Enviar WhatsApp y NO servia: estaba escrito
// /^Calling tools\b/i dentro del JSON del workflow, y en JSON \b es el
// caracter backspace (0x08), no el limite de palabra del regex. El regex
// pedia un backspace literal despues de "tools" y no caso ni una vez desde
// que se escribio. Aqui no se usa \b a proposito.
const FUGAS = [
  /^calling tools/i,
  /^\s*(functioncall|function_call|tool_code|tool_call|tool_use)/i,
  /^\s*\{/,
  /(enviar_medios|agendar_cita|separar_fecha_evento|cerrar_seguimiento|consultar_precios_sedes|consultar_inclusiones_evento|consultar_servicios_upselling|verificar_disponibilidad_evento)\s*\{/i,
  /tipo_medio\s*:/i,
];
const AVISO = 'Dame un segundito que confirmo eso y te cuento 🤗';

const texto = String($json.output ?? '').trim();

if (texto === '' || FUGAS.some((r) => r.test(texto))) {
  return [{ json: { output: AVISO, fuga: true }, pairedItem: { item: 0 } }];
}

const partes = texto
  .split(/\s*\|\|\|\s*/)
  .map((p) => p.trim())
  .filter((p) => p.length > 0);

return (partes.length ? partes : [texto]).map((p) => ({
  json: { output: p },
  pairedItem: { item: 0 },
}));

// ¿Este mensaje esta completo, o el cliente lo esta escribiendo por partes?
//
// EL PROBLEMA (produccion, 2026-08-27). Mucha gente escribe asi:
//     quiero / que sea / para 150 / personas
// y el agente contestaba los cuatro, uno por uno. Ninguna de las cuatro
// respuestas podia tener sentido, porque ninguno de los cuatro mensajes lo
// tenia. Se lee como una maquina disparando.
//
// LA REGLA QUE NO SE PUEDE ROMPER: los tramos que ya funcionaban bien no pueden
// volverse mas lentos. Un cliente que escribe "si", "Miguel", "150" o "me gusto
// Casa Christian's" tiene que seguir recibiendo respuesta de una. Por eso esto
// NO es "si el mensaje es corto, espera": corto y completo es el caso mas comun
// de toda la conversacion.
//
// DE AHI SALE LA FORMA DE LA REGLA, que es lo unico que hay que entender aqui:
//
//   El PRIMER mensaje solo espera si es gramaticalmente IMPOSIBLE que ahi
//   termine la frase -- "quiero", "que sea", "para". Nada mas. Un mensaje corto
//   y normal ("si", "150", "Casa 4") nunca espera.
//
//   Una vez la rafaga ya arranco, la vara baja: cualquier mensaje corto se le
//   suma, porque el cliente ya demostro que esta escribiendo por pedazos. Asi
//   es como "personas" -- un sustantivo suelto, indistinguible de una respuesta
//   completa -- termina donde tiene que terminar.
//
// El costo para una conversacion normal es de dos consultas a la base y cero
// segundos de espera.
const LARGO_MAXIMO = 140;   // mas que esto ya es un mensaje, no un pedazo
const CORTO = 45;           // hasta aqui, dentro de una rafaga, se considera pedazo
const SEGUNDOS_DE_ESPERA = 8;

// Palabras que NO pueden cerrar una frase en español. Si el mensaje termina en
// una de estas, falta lo que sigue. Es la unica senal que puede ABRIR una
// rafaga, asi que aqui no entra nada dudoso.
const ABREN = new Set([
  // conjunciones y nexos
  'y', 'e', 'o', 'u', 'ni', 'pero', 'sino', 'que', 'porque', 'pues', 'aunque',
  'mientras', 'cuando', 'donde', 'como', 'si', 'segun',
  // preposiciones
  'a', 'ante', 'bajo', 'con', 'contra', 'de', 'desde', 'durante', 'en',
  'entre', 'hacia', 'hasta', 'para', 'por', 'sin', 'sobre', 'tras', 'del', 'al',
  // articulos y determinantes
  'el', 'la', 'los', 'las', 'un', 'una', 'unos', 'unas', 'lo',
  'mi', 'mis', 'tu', 'tus', 'su', 'sus', 'nuestro', 'nuestra',
  'este', 'esta', 'estos', 'estas', 'ese', 'esa', 'esos', 'esas',
  'otro', 'otra', 'otros', 'otras', 'cada', 'algun', 'alguna', 'todo', 'toda',
  // pronombres atonos y relativos
  'me', 'te', 'se', 'le', 'les', 'nos', 'cual', 'cuales', 'quien', 'quienes',
  // verbos que piden complemento si o si
  'quiero', 'queria', 'quisiera', 'quisieramos', 'necesito', 'necesitaria',
  'busco', 'buscaba', 'tengo', 'tenia', 'seria', 'sera', 'serian', 'es', 'son',
  'era', 'eran', 'estan', 'estoy', 'estaba', 'estamos', 'hay', 'habia', 'va',
  'van', 'iba', 'sea', 'fuera', 'fue', 'puede', 'podria', 'gustaria', 'pienso',
  'pensaba', 'somos', 'seremos',
  // cuantificadores y adverbios que anteceden
  'muy', 'mas', 'menos', 'tan', 'casi', 'aproximadamente', 'alrededor',
  'cerca', 'tambien', 'ademas',
  // Verbos de gustar y de elegir. Van aqui por un chat real (2026-08-29):
  // el cliente contesto "cual te llamo mas la atencion" con "Me gusto" y,
  // 1,6 s despues, "El Marquez". Como "gusto" no abria rafaga, el primero
  // se contesto solo y los dos pedazos recibieron respuestas cruzadas.
  // En este embudo estos verbos van siempre seguidos de QUE fue lo que le
  // gusto: sin complemento, el mensaje no dice nada que se pueda contestar.
  'gusto', 'gusta', 'gustan', 'gustaron', 'encanto', 'encanta', 'encantan',
  'encantaron', 'llamo', 'llamaron', 'prefiero', 'prefiere', 'escojo',
  'escogi', 'elijo', 'elegi', 'interesa', 'interesan',
]);

// Respuestas que se dicen solas y cierran. Van ANTES de ABREN porque varias
// caen en las dos listas una vez pelado el acento: "si" (condicional) y "si"
// (afirmacion) se escriben igual, y la afirmacion es muchisimo mas frecuente.
// Sin esta lista, cada "si" del cliente esperaba ocho segundos.
const SUELTAS = new Set([
  'si', 'sip', 'no', 'nop', 'ok', 'oka', 'okay', 'listo', 'dale', 'claro',
  'bueno', 'buenas', 'buenos', 'hola', 'gracias', 'perfecto', 'vale', 'va',
  'ya', 'aja', 'ah', 'como', 'cuando', 'cuanto', 'donde', 'cual', 'quien',
  'porque', 'ninguno', 'ninguna', 'ambos', 'todos', 'todas', 'igual', 'chao',
]);

// Un mensaje que empieza por uno de estos es continuacion de algo. Solo cuenta
// DENTRO de una rafaga ya abierta: como primer mensaje, "y cuanto vale" es una
// pregunta completa y esperar por ella seria justo lo que no queremos.
const CONTINUAN = new Set([
  'y', 'e', 'o', 'u', 'ni', 'pero', 'sino', 'que', 'porque', 'pues', 'aunque',
  'para', 'por', 'con', 'sin', 'de', 'del', 'en', 'a', 'al', 'desde', 'hasta',
  'entre', 'sobre', 'tambien', 'ademas', 'osea', 'mas',
]);

// Sin tildes, sin signos, sin emojis: para comparar contra las listas.
function pelar(s) {
  return s
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(/ +/g, ' ')
    .trim();
}

// `pendientes` es cuantos pedazos de este cliente estan esperando, incluido
// este. Con 1, el mensaje es el primero y solo una senal fuerte abre la rafaga.
function esFragmento(crudo, pendientes) {
  const texto = (crudo ?? '').toString().trim();
  if (texto === '') return { esperar: false, motivo: 'vacio' };

  // Un mensaje largo se defiende solo, aunque termine en preposicion.
  if (texto.length > LARGO_MAXIMO) return { esperar: false, motivo: 'es largo, va completo' };

  // Puntuacion de cierre: el cliente dio la frase por terminada.
  if (/[.!?)]$/.test(texto) && !/[.][.][.]$/.test(texto)) {
    return { esperar: false, motivo: 'cierra con puntuacion' };
  }
  // Y al reves: suspensivos, coma o dos puntos al final son "sigo escribiendo".
  if (/([.][.][.]|,|:|;)$/.test(texto)) return { esperar: true, motivo: 'el signo lo deja abierto' };

  const limpio = pelar(texto);
  if (limpio === '') return { esperar: false, motivo: 'solo emojis o signos' };

  const palabras = limpio.split(' ');
  const ultima = palabras[palabras.length - 1];
  const primera = palabras[0];

  // Una respuesta de una sola palabra que cierra. Antes que todo lo demas.
  if (palabras.length === 1 && SUELTAS.has(limpio)) {
    return { esperar: false, motivo: 'respuesta suelta' };
  }

  // LA UNICA SENAL QUE ABRE UNA RAFAGA: termina en palabra que no puede cerrar.
  if (ABREN.has(ultima)) return { esperar: true, motivo: 'termina en "' + ultima + '"' };

  // De aqui para abajo, solo si la rafaga YA venia.
  if (pendientes > 1) {
    if (CONTINUAN.has(primera) && palabras.length <= 6) {
      return { esperar: true, motivo: 'arranca con "' + primera + '" y la rafaga ya venia' };
    }
    if (texto.length <= CORTO && palabras.length <= 4) {
      return { esperar: true, motivo: 'se suma a la rafaga que ya venia' };
    }
  }

  return { esperar: false, motivo: 'se lee completo' };
}

const entrada = $input.first().json;
const veredicto = esFragmento(entrada.texto, entrada.pendientes);

return [{
  json: {
    id: entrada.id,
    telefono: entrada.telefono,
    texto: entrada.texto,
    pendientes: entrada.pendientes,
    esperar: veredicto.esperar,
    motivo: veredicto.motivo,
    espera_seg: SEGUNDOS_DE_ESPERA,
  },
}];
